import XCTest
@testable import AppCore

/// The backend keeps its own copy of the template recipes
/// (backend/supabase/functions/_shared/catalog.json, generated by
/// scripts/export-catalog.sh). This fails if the two drift apart.
final class CatalogSyncTests: XCTestCase {
    private struct Catalog: Decodable {
        struct Recipe: Decodable {
            let id: String
            let isPro: Bool
            let prompt: String
        }

        let templates: [Recipe]
        let proStyles: [String]
    }

    func testBackendCatalogMatchesApp() throws {
        let url = try RepositoryFile.url("backend/supabase/functions/_shared/catalog.json")
        let catalog = try JSONDecoder().decode(Catalog.self, from: Data(contentsOf: url))

        XCTAssertEqual(catalog.templates.map(\.id), TemplateCatalog.all.map(\.id), "Run scripts/export-catalog.sh")
        for (server, app) in zip(catalog.templates, TemplateCatalog.all) {
            XCTAssertEqual(server.prompt, app.prompt, "\(app.id): run scripts/export-catalog.sh")
            XCTAssertEqual(server.isPro, app.isPro, app.id)
        }
        XCTAssertEqual(Set(catalog.proStyles), Set(StyleCatalog.all.filter(\.isPro).map(\.id)))
    }
}
